import React, { useRef } from "react";
import { Badge } from "@/components/ui/badge";
import { AnimatedBeam } from "@/components/ui/animated-beam";
import {
  Globe,
  Smartphone,
  Code2,
  ShieldCheck,
  Cpu,
  ScanFace,
  ServerCog,
  Database,
  GitMerge,
  BarChart2,
  KeyRound,
  Layers,
  Share2,
} from "lucide-react";

/* ΓöÇΓöÇΓöÇ Node data ΓöÇΓöÇΓöÇ */
const LEFT_NODES = [
  { id: "web", icon: Globe, title: "Web Client", color: "#3b82f6" },
  { id: "mobile", icon: Smartphone, title: "Mobile SDK", color: "#a855f7" },
  { id: "server", icon: Code2, title: "Server SDK", color: "#f97316" },
  { id: "oauth", icon: ShieldCheck, title: "OAuth 2.1", color: "#ec4899" },
  { id: "iot", icon: Cpu, title: "IoT Edge", color: "#eab308" },
  { id: "biometrics", icon: ScanFace, title: "Biometrics", color: "#f43f5e" },
];

const RIGHT_NODES = [
  { id: "rpc", icon: ServerCog, title: "gRPC Cluster", color: "#10b981" },
  { id: "db", icon: Database, title: "Postgres XL", color: "#f59e0b" },
  { id: "stream", icon: GitMerge, title: "Kafka Mesh", color: "#6366f1" },
  { id: "analytics", icon: BarChart2, title: "Realtime BI", color: "#06b6d4" },
  { id: "vault", icon: KeyRound, title: "Vault HSM", color: "#8b5cf6" },
  { id: "cache", icon: Layers, title: "Redis Cache", color: "#84cc16" },
];

/* ΓöÇΓöÇΓöÇ Single node card ΓöÇΓöÇΓöÇ */
const ArchNode = React.forwardRef(({ icon: Icon, title, color }, ref) => (
  <div
    ref={ref}
    className="group z-40 flex items-center gap-2.5 px-3 py-2.5 rounded-xl
               bg-background border border-border/50 hover:border-border/90
               hover:shadow-sm transition-all duration-200 w-full"
  >
    <div
      className="shrink-0 h-7 w-7 rounded-lg border flex items-center justify-center
                 transition-transform duration-300 group-hover:scale-105"
      style={{ backgroundColor: `${color}14`, borderColor: `${color}28` }}
    >
      <Icon style={{ color }} className="h-3.5 w-3.5" />
    </div>
    <span
      className="text-[11px] font-semibold tracking-tight text-muted-foreground
                     group-hover:text-foreground transition-colors truncate leading-none"
    >
      {title}
    </span>
  </div>
));
ArchNode.displayName = "ArchNode";

/* ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */
const Architecture = () => {
  const containerRef = useRef(null);
  const coreRef = useRef(null);

  const leftRefs = React.useMemo(
    () => LEFT_NODES.map(() => React.createRef()),
    [],
  );
  const rightRefs = React.useMemo(
    () => RIGHT_NODES.map(() => React.createRef()),
    [],
  );

  return (
    <section
      ref={containerRef}
      className="relative py-20 sm:py-28 overflow-hidden bg-transparent"
    >
      {/* ΓöÇΓöÇ Soft grid ΓöÇΓöÇ */}
      <div
        className="absolute inset-0 pointer-events-none opacity-40 dark:opacity-20"
        style={{
          backgroundImage:
            "linear-gradient(to right,hsl(var(--border)/0.5) 1px,transparent 1px)," +
            "linear-gradient(to bottom,hsl(var(--border)/0.5) 1px,transparent 1px)",
          backgroundSize: "36px 36px",
          maskImage:
            "radial-gradient(ellipse 70% 60% at 50% 50%,#000 60%,transparent 100%)",
        }}
      />

      <div className="relative z-10 mx-auto w-[92%] max-w-7xl">
        {/* ΓöÇΓöÇ Section header ΓöÇΓöÇ */}
        <div className="flex flex-col items-center gap-3 mb-16 sm:mb-20 text-center">
          <Badge
            variant="outline"
            className="rounded-full border-primary/20 bg-primary/5 text-primary
                       text-[9px] font-bold tracking-[0.15em] uppercase px-3 py-0.5"
          >
            System Topology
          </Badge>

          <h2
            className="text-3xl sm:text-4xl md:text-5xl font-semibold tracking-tight
                         text-foreground leading-tight"
          >
            Integrated{" "}
            <span className="text-muted-foreground/40 font-light italic">
              Security Mesh
            </span>
          </h2>

          <p className="text-[13px] sm:text-sm text-muted-foreground max-w-sm sm:max-w-md leading-relaxed">
            Real-time data orchestration between edge nodes and core
            infrastructure ΓÇö visualised end-to-end.
          </p>
        </div>

        {/* ΓöÇΓöÇ Three-column diagram ΓöÇΓöÇ */}
        <div className="flex flex-col lg:flex-row items-center justify-between gap-8 lg:gap-6 relative">
          {/* Left column */}
          <div className="grid grid-cols-2 lg:grid-cols-1 gap-2.5 w-full lg:w-[185px] lg:shrink-0">
            {LEFT_NODES.map((node, i) => (
              <ArchNode key={node.id} ref={leftRefs[i]} {...node} />
            ))}
          </div>

          {/* Center hub */}
          <div className="relative flex items-center justify-center shrink-0 my-2 lg:my-0">
            {/* Outer ring */}
            <div className="absolute h-52 w-52 sm:h-60 sm:w-60 rounded-full border border-dashed border-border/30 animate-[spin_30s_linear_infinite]" />
            <div className="absolute h-36 w-36 sm:h-40 sm:w-40 rounded-full border border-dashed border-border/20 animate-[spin_20s_linear_infinite_reverse]" />

            {/* Hub card */}
            <div
              ref={coreRef}
              className="relative z-50 h-36 w-36 sm:h-40 sm:w-40 rounded-[2rem] bg-background
                         border border-border shadow-[0_8px_40px_rgba(0,0,0,.08)]
                         flex flex-col items-center justify-center gap-3 group"
            >
              <div
                className="h-12 w-12 rounded-2xl bg-muted border border-border flex items-center
                              justify-center transition-transform duration-500 group-hover:scale-105"
              >
                <Share2 className="h-5 w-5 text-foreground" />
              </div>

              <div className="flex flex-col items-center gap-1">
                <span className="text-[10px] font-bold tracking-[0.14em] text-foreground uppercase">
                  AuthSphere
                </span>
                <div className="flex items-center gap-1">
                  <span className="relative flex h-1.5 w-1.5">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75" />
                    <span className="relative inline-flex h-1.5 w-1.5 rounded-full bg-emerald-500" />
                  </span>
                  <span className="text-[9px] font-semibold text-muted-foreground tracking-wider uppercase">
                    Primary Hub
                  </span>
                </div>
              </div>
            </div>
          </div>

          {/* Right column */}
          <div className="grid grid-cols-2 lg:grid-cols-1 gap-2.5 w-full lg:w-[185px] lg:shrink-0">
            {RIGHT_NODES.map((node, i) => (
              <ArchNode key={node.id} ref={rightRefs[i]} {...node} />
            ))}
          </div>
        </div>

        {/* ΓöÇΓöÇ Bottom legend ΓöÇΓöÇ */}
        <div className="flex flex-wrap items-center justify-center gap-x-6 gap-y-2 mt-14 sm:mt-16">
          {[
            { dot: "bg-blue-500", label: "Client surfaces" },
            { dot: "bg-primary", label: "AuthSphere core" },
            { dot: "bg-emerald-500", label: "Backend infrastructure" },
          ].map(({ dot, label }) => (
            <div key={label} className="flex items-center gap-1.5">
              <div className={`h-1.5 w-1.5 rounded-full ${dot}`} />
              <span className="text-[11px] text-muted-foreground">{label}</span>
            </div>
          ))}
        </div>
      </div>

      {/* ΓöÇΓöÇ Beams: left ΓåÆ core ΓöÇΓöÇ */}
      {LEFT_NODES.map((node, i) => (
        <AnimatedBeam
          key={`l-${node.id}`}
          containerRef={containerRef}
          fromRef={leftRefs[i]}
          toRef={coreRef}
          duration={3 + i * 0.45}
          curvature={i < 3 ? -35 : 35}
          pathColor={node.color}
          gradientStartColor={node.color}
          gradientStopColor={node.color}
          pathWidth={1.2}
          pathOpacity={0.22}
        />
      ))}

      {/* ΓöÇΓöÇ Beams: core ΓåÆ right ΓöÇΓöÇ */}
      {RIGHT_NODES.map((node, i) => (
        <AnimatedBeam
          key={`r-${node.id}`}
          containerRef={containerRef}
          fromRef={coreRef}
          toRef={rightRefs[i]}
          duration={3 + i * 0.4}
          curvature={i < 3 ? -35 : 35}
          pathColor={node.color}
          gradientStartColor={node.color}
          gradientStopColor={node.color}
          pathWidth={1.2}
          pathOpacity={0.22}
        />
      ))}
    </section>
  );
};

export default Architecture;

import React from "react";
import { Badge } from "@/components/ui/badge";
import { ArrowUpRight } from "lucide-react";

/* ΓöÇΓöÇΓöÇ Single schema card ΓöÇΓöÇΓöÇ */
const SchemaNode = ({ title, label, icon: Icon, color, fields }) => (
  <div className="group relative flex flex-col bg-background border-r border-b border-border/50 last:border-r-0 p-6 hover:bg-muted/20 transition-colors duration-200">
    {/* Header */}
    <div className="flex items-start justify-between mb-5">
      <div
        className="h-9 w-9 rounded-xl border flex items-center justify-center shrink-0
                   transition-transform duration-300 group-hover:scale-105"
        style={{ backgroundColor: `${color}12`, borderColor: `${color}25` }}
      >
        <Icon className="h-4 w-4" style={{ color }} />
      </div>
      <ArrowUpRight className="h-3.5 w-3.5 text-border group-hover:text-primary transition-colors duration-200 mt-0.5" />
    </div>

    {/* Title */}
    <div className="mb-5">
      <p className="text-[9px] font-bold text-primary/60 uppercase tracking-[0.18em] mb-1">
        {label}
      </p>
      <h3 className="text-lg font-semibold tracking-tight text-foreground">
        {title}
      </h3>
    </div>

    {/* Field rows */}
    <div className="flex flex-col gap-2.5 font-mono">
      {fields.map((field, i) => (
        <div
          key={field.id}
          className="flex items-center justify-between py-1.5 border-b border-border/30 last:border-0"
        >
          <span className="text-[11px] text-muted-foreground group-hover:text-foreground/80 transition-colors">
            {field.id}
          </span>
          <span
            className="text-[9px] font-semibold px-1.5 py-0.5 rounded-md"
            style={{ backgroundColor: `${color}10`, color }}
          >
            {field.type}
          </span>
        </div>
      ))}
    </div>
  </div>
);

/* ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */
const DataModel = ({ schemas = [] }) => (
  <section className="relative py-20 sm:py-28 bg-transparent overflow-hidden">
    <div className="mx-auto w-[92%] max-w-7xl">
      {/* ΓöÇΓöÇ Header ΓöÇΓöÇ */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-14 sm:mb-16">
        <div className="flex flex-col gap-3">
          <Badge
            variant="outline"
            className="w-fit rounded-full border-primary/20 bg-primary/5 text-primary
                       text-[9px] font-bold tracking-[0.15em] uppercase px-3 py-0.5"
          >
            Technical Specification
          </Badge>
          <h2 className="text-3xl sm:text-4xl md:text-5xl font-semibold tracking-tight text-foreground leading-tight">
            Data{" "}
            <span className="text-muted-foreground/40 font-light italic">
              Architecture.
            </span>
          </h2>
        </div>

        <p className="text-[12px] font-mono text-muted-foreground leading-relaxed max-w-xs md:max-w-sm md:text-right md:pb-1">
          {"// "}Scalable schema for high-throughput environments ΓÇö built on
          immutable primitives with cryptographic indexing and O(1) retrieval.
        </p>
      </div>

      {/* ΓöÇΓöÇ Grid ΓöÇΓöÇ */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 border border-border/50 rounded-2xl overflow-hidden divide-y sm:divide-y-0 sm:divide-x divide-border/40">
        {schemas.map((schema) => (
          <SchemaNode key={schema.title} {...schema} />
        ))}
      </div>

      {/* ΓöÇΓöÇ Footer note ΓöÇΓöÇ */}
      <div className="flex flex-wrap items-center justify-between gap-3 mt-5 px-1">
        <p className="text-[11px] text-muted-foreground/50 font-mono">
          4 collections ┬╖ 16 fields ┬╖ AES-256 encrypted at rest
        </p>
        <div className="flex items-center gap-1.5">
          <span className="relative flex h-1.5 w-1.5">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-70" />
            <span className="relative inline-flex h-1.5 w-1.5 rounded-full bg-emerald-500" />
          </span>
          <span className="text-[10px] font-semibold text-muted-foreground/60 uppercase tracking-wider">
            Schema synced
          </span>
        </div>
      </div>
    </div>
  </section>
);

export default DataModel;

import React, { useState, useEffect } from "react";
import { Terminal, ChevronRight, Cpu, ShieldCheck, Loader2, AlertCircle } from "lucide-react";
import { useTranslation } from "react-i18next";
import { motion } from "framer-motion"; // eslint-disable-line no-unused-vars

export const DeveloperLogin = () => {
  const { t } = useTranslation();
  const [cursorVisible, setCursorVisible] = useState(true);
  const [timestamp, setTimestamp] = useState(() => new Date().toUTCString());
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({ identity: "", passkey: "" });
  const [errors, setErrors] = useState({});

  useEffect(() => {
    const interval = setInterval(() => setCursorVisible((v) => !v), 500);
    return () => clearInterval(interval);
  }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    const newErrors = {};
    if (!formData.identity.includes("@")) newErrors.identity = true;
    if (formData.passkey.length < 6) newErrors.passkey = true;

    setErrors(newErrors);

    if (Object.keys(newErrors).length === 0) {
      setLoading(true);
      setTimeout(() => setLoading(false), 1500);
    }
  };

  return (
    <div className="h-full w-full flex items-center justify-center bg-zinc-950 p-[5%] font-mono text-green-500 relative overflow-hidden">
      {/* Ambient CRT Scanline Effect */}
      <div className="absolute inset-0 pointer-events-none bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.1)_50%),linear-gradient(90deg,rgba(255,0,0,0.03),rgba(0,255,0,0.01),rgba(0,0,255,0.03))] bg-[length:100%_4px,3px_100%] z-50" aria-hidden="true"></div>

      {/* Main Terminal Window */}
      <div className="w-full max-w-[95%] md:max-w-[60%] lg:max-w-[40%] border border-green-500/30 rounded-sm bg-black shadow-[0_0_40px_rgba(0,255,0,0.05)] p-[6%] relative flex flex-col gap-[8%]">
        {/* Terminal Header */}
        <div className="flex items-center justify-between border-b border-green-500/20 pb-[4%] opacity-60" aria-hidden="true">
          <div className="flex gap-[0.5rem]">
            <div className="w-[0.75rem] h-[0.75rem] rounded-full bg-red-900/40 border border-red-500/20"></div>
            <div className="w-[0.75rem] h-[0.75rem] rounded-full bg-yellow-900/40 border border-yellow-500/20"></div>
            <div className="w-[0.75rem] h-[0.75rem] rounded-full bg-green-900/40 border border-green-500/20"></div>
          </div>
          <div className="text-[0.7rem] tracking-widest flex items-center gap-[0.5rem]">
            <Cpu className="w-[0.8rem] h-[0.8rem]" />
            {t("developer.session", "SESSION: 0x7FF8")}
          </div>
        </div>

        {/* Body Content */}
        <div className="flex flex-col gap-[6%]">
          <div className="space-y-[1%]">
            <p className="text-[0.75rem] opacity-50 uppercase tracking-tighter" aria-live="polite">
              {t("developer.last_connection", "Last connection:")} {timestamp}
            </p>
            <h2 className="text-[1.5rem] font-bold tracking-[0.2rem] text-white flex items-center gap-[1rem]">
              <ShieldCheck className="w-[1.5rem] h-[1.5rem] text-green-500" aria-hidden="true" />
              {t("developer.root_access", "ROOT_ACCESS")}
            </h2>
          </div>

          {/* Form Logic */}
          <form className="flex flex-col gap-[10%] pt-[4%]" onSubmit={handleSubmit} aria-label={t("developer.form_aria", "Terminal Authentication Form")}>
            <div className={`group border-l-2 pl-[4%] transition-colors relative ${errors.identity ? 'border-red-500' : 'border-green-900/50 focus-within:border-green-400'}`}>
              <label htmlFor="identity" className={`block text-[0.65rem] uppercase tracking-[0.3rem] mb-[2%] ${errors.identity ? 'text-red-500 opacity-80' : 'opacity-40'}`}>
                {t("developer.identity", "Identity")}
              </label>
              <motion.div animate={errors.identity ? { x: [-10, 10, -10, 10, 0] } : {}} transition={{ duration: 0.4 }} className="flex items-center py-[2%]">
                <span className={`mr-[3%] font-bold ${errors.identity ? 'text-red-500' : 'text-green-600'}`} aria-hidden="true">#</span>
                <input
                  id="identity"
                  type="email"
                  required
                  aria-required="true"
                  aria-invalid={errors.identity ? "true" : "false"}
                  aria-describedby={errors.identity ? "identity-error" : undefined}
                  autoComplete="off"
                  placeholder="ssh_user@host"
                  className={`bg-transparent border-none w-full focus:outline-none text-[1rem] ${errors.identity ? 'text-red-400 placeholder-red-900/50' : 'text-green-400 placeholder-green-900/50'}`}
                  value={formData.identity}
                  onChange={(e) => {
                    setFormData({...formData, identity: e.target.value});
                    if (errors.identity) setErrors({...errors, identity: false});
                  }}
                />
                {errors.identity && <AlertCircle className="w-4 h-4 text-red-500" aria-hidden="true" />}
              </motion.div>
              {errors.identity && <p id="identity-error" className="absolute -bottom-4 left-[6%] text-[10px] text-red-500 uppercase tracking-widest" role="alert">{t("developer.identity_error", "INVALID_IDENTITY")}</p>}
            </div>

            <div className={`group border-l-2 pl-[4%] transition-colors relative ${errors.passkey ? 'border-red-500' : 'border-green-900/50 focus-within:border-green-400'}`}>
              <label htmlFor="passkey" className={`block text-[0.65rem] uppercase tracking-[0.3rem] mb-[2%] ${errors.passkey ? 'text-red-500 opacity-80' : 'opacity-40'}`}>
                {t("developer.passkey", "Passkey")}
              </label>
              <motion.div animate={errors.passkey ? { x: [-10, 10, -10, 10, 0] } : {}} transition={{ duration: 0.4 }} className="flex items-center py-[2%]">
                <span className={`mr-[3%] font-bold ${errors.passkey ? 'text-red-500' : 'text-green-600'}`} aria-hidden="true">#</span>
                <input
                  id="passkey"
                  type="password"
                  required
                  aria-required="true"
                  aria-invalid={errors.passkey ? "true" : "false"}
                  aria-describedby={errors.passkey ? "passkey-error" : undefined}
                  autoComplete="off"
                  placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
                  className={`bg-transparent border-none w-full focus:outline-none text-[1rem] ${errors.passkey ? 'text-red-400 placeholder-red-900/50' : 'text-green-400 placeholder-green-900/50'}`}
                  value={formData.passkey}
                  onChange={(e) => {
                    setFormData({...formData, passkey: e.target.value});
                    if (errors.passkey) setErrors({...errors, passkey: false});
                  }}
                />
                {errors.passkey && <AlertCircle className="w-4 h-4 text-red-500" aria-hidden="true" />}
              </motion.div>
              {errors.passkey && <p id="passkey-error" className="absolute -bottom-4 left-[6%] text-[10px] text-red-500 uppercase tracking-widest" role="alert">{t("developer.passkey_error", "ACCESS_DENIED")}</p>}
            </div>

            {/* Action Button */}
            <button 
              disabled={loading}
              aria-live="polite"
              className="w-full mt-[5%] bg-green-500/5 border border-green-500/40 text-green-500 hover:bg-green-500 hover:text-black transition-all py-[4%] px-[5%] font-bold flex items-center justify-between group overflow-hidden relative disabled:opacity-50"
            >
              <div className="flex items-center gap-[0.8rem]">
                {loading ? <Loader2 className="w-[1.2rem] h-[1.2rem] animate-spin" aria-hidden="true" /> : <Terminal className="w-[1rem] h-[1rem]" aria-hidden="true" />}
                <span className="tracking-[0.2rem] text-[0.9rem]">
                  {loading ? t("developer.executing", "EXECUTING...") : t("developer.execute_login", "EXECUTE LOGIN")}
                </span>
              </div>
              {!loading && <ChevronRight className="w-[1.2rem] h-[1.2rem] group-hover:translate-x-[20%] transition-transform" aria-hidden="true" />}

              {/* Subtle background slide effect */}
              <div className="absolute inset-0 bg-green-500 -translate-x-full group-hover:translate-x-0 transition-transform -z-10" aria-hidden="true"></div>
            </button>
          </form>

          {/* Status Footer */}
          <div className="text-[0.65rem] opacity-30 pt-[4%] flex justify-between items-center border-t border-green-500/10" aria-hidden="true">
            <div className="flex items-center gap-[0.5rem]">
              <span className="animate-pulse">ΓùÅ</span>
              {t("developer.enc_mode", "ENC_MODE: AES-256")}
            </div>
            <div>
              {t("developer.sec_level", "SEC_LEVEL: ALPHA")}{" "}
              <span
                className={`${cursorVisible ? "opacity-100" : "opacity-0"}`}
              >
                Γûê
              </span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

